"""Drop unusable rows and resolve duplicates (DATA-02)."""

from __future__ import annotations

from collections.abc import Sequence

from mdata.types import RawRow


def validate_rows(rows: Sequence[RawRow], tickers: Sequence[str] | None = None) -> list[RawRow]:
    """Rows with a close, for the requested tickers (all if None), sorted by (date, ticker)."""
    kept = [
        row
        for row in rows
        if row.close is not None and (tickers is None or row.ticker in tickers)
    ]
    return sorted(kept, key=lambda row: (row.date, row.ticker))

